Drupal.behaviors.mediaGridInteractive = {
  attach(context) {
    const mediaGrids = once(
      'media-grid-interactive',
      '.media-grid[data-media-grid-variation="interactive"]',
      context,
    );
    const focusableElements =
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
    const body = document.querySelector('body');
    const activeItemIndicator = 'data-media-grid-modal-item-active';
    const ariaCurrent = 'aria-current';

    mediaGrids.forEach((grid) => {
      const items = grid.querySelectorAll('.media-grid__image');
      const maximizeIcons = grid.querySelectorAll('.media-grid__maximize');
      const modal = grid.querySelector('.media-grid__modal');
      const modalMedia = grid.querySelectorAll('.media-grid-modal__media');
      const controls = grid.querySelectorAll('.media-grid-modal__control');
      const itemCount = grid.querySelectorAll('[data-media-grid-item]').length;
      const pagerItems = grid.querySelectorAll(
        '.media-grid-modal__pager-item:not(.media-grid-modal__pager-item--total)',
      );
      let activeIndex;
      let swipeStartX;
      let swipeEndX;
      // Captions that collapse behind the expand toggle. Their collapsed height
      // is measured on first open (see toggleModalState), not at attach, because
      // the modal is `display: none` while inactive and offsetHeight would read 0.
      const collapsibleCaptions = [];

      /**
       * trapKeyboard
       * @description traps keyboard focus when modal is active.
       */
      const trapKeyboard = () => {
        const focusableModalElements =
          modal.querySelectorAll(focusableElements);
        const firstFocusableElement = focusableModalElements[0];
        const lastFocusableElement =
          focusableModalElements[focusableModalElements.length - 1];

        // Set initial focus inside modal when opened.
        firstFocusableElement.focus();

        modal.addEventListener('keydown', (e) => {
          const isTabPressed = e.key === 'Tab' || e.keyCode === 9;

          if (!isTabPressed) {
            return;
          }

          if (e.shiftKey) {
            if (document.activeElement === firstFocusableElement) {
              e.preventDefault();

              lastFocusableElement.focus();
            }
          } else if (document.activeElement === lastFocusableElement) {
            e.preventDefault();

            firstFocusableElement.focus();
          }
        });
      };

      /**
       * toggleModalState
       * @description toggleModalState toggles modal state.
       * @param {Enumerator} currentState the current state the modal is in.
       */
      const toggleModalState = (currentState) => {
        const newState = currentState === 'inactive' ? 'active' : 'inactive';

        grid.setAttribute('data-media-grid-modal-state', newState);

        // On close, set focus on the grid item that was just open in the modal.
        if (newState === 'inactive') {
          grid
            .querySelector(`[data-media-grid-item="${activeIndex}"`)
            .querySelector('button')
            .focus();
          body.removeAttribute('data-modal-active');
        } else if (newState === 'active') {
          // Now that the modal is displayed, measure each truncated caption's
          // collapsed height once (offsetHeight is 0 while the modal is
          // `display: none`, so this cannot be measured at attach time).
          collapsibleCaptions.forEach((caption) => {
            if (
              !caption.style.getPropertyValue('--modal-content-item-height')
            ) {
              caption.style.setProperty(
                '--modal-content-item-height',
                `${caption.offsetHeight}px`,
              );
            }
          });
          trapKeyboard();
          body.setAttribute('data-modal-active', 'true');
        }
      };

      /**
       * indicateActivePager
       * @description visually indicate active pager item.
       */
      const indicateActivePager = (index) => {
        pagerItems.forEach((pagerItem, itemIndex) => {
          pagerItem.removeAttribute(ariaCurrent);

          if (index - 1 === itemIndex) {
            pagerItem.setAttribute(ariaCurrent, true);
          }
        });
      };

      /**
       * showSelectedItem
       * @description showSelectedItem makes the selected item visible in the modal.
       * @param {Number} index the item number of the item to show.
       */
      const showSelectedItem = (index) => {
        activeIndex = index;

        const modalItems = grid.querySelectorAll(
          '[data-media-grid-modal-item]',
        );
        const activeModalItem = grid.querySelectorAll(
          `[data-media-grid-modal-item="${index}"]`,
        );

        // Hide inactive items.
        modalItems.forEach((modalItem) => {
          modalItem.removeAttribute(activeItemIndicator);
        });

        // Show active item.
        activeModalItem.forEach((activeItem) => {
          activeItem.setAttribute(activeItemIndicator, true);
        });

        // Indicate active pager item.
        indicateActivePager(activeIndex);
      };

      /**
       * toggleCaptions
       * @description toggleCaptions truncates long captions visible in the modal.
       */

      // Truncate caption function
      // Take a string and a maxlength parameter
      // slice the string starting at 0 and ending at maxLength.
      function handleCaptionTruncation(captionContent, maxLength) {
        return captionContent.length > maxLength
          ? captionContent.slice(0, maxLength)
          : captionContent;
      }

      // Get all modal content.
      const imageCaptions = grid.querySelectorAll('.media-grid-modal__content');

      // Set variables for each modal content/caption.
      imageCaptions.forEach((imageCaption) => {
        const captionContent = imageCaption.querySelector(
          '.media-grid-modal__text',
        );

        const toggleCaption = imageCaption.querySelector(
          '.media-grid-modal__toggle-caption',
        );

        const captionHeading = imageCaption.querySelector(
          '.media-grid-modal__heading',
        );

        const hasHeading = !!captionHeading;

        // A cheap early-out: with neither present there is nothing to collapse.
        // Not load-bearing any more — the toggle gate below rejects that case on
        // its own — but it keeps the caption work visibly scoped to captions.
        if (captionContent || hasHeading) {
          const maxLength = 100;

          const fullCaption = captionContent
            ? captionContent.textContent.trim()
            : '';

          if (hasHeading && captionContent) {
            captionContent.classList.add('media-grid-modal__text--has-heading');
          }

          // A heading hides the caption body entirely via CSS while
          // collapsed, so any non-empty body counts as hidden content;
          // without a heading it's only hidden once truncation kicks in.
          const hasHiddenContent = hasHeading
            ? fullCaption.length > 0
            : fullCaption.length > maxLength;

          if (toggleCaption && hasHiddenContent) {
            let truncatedCaption;
            let fullCaptionNodes;

            // The SCSS one-line clamp keys off this, so it has to be set here
            // with the toggle — a caption with no way to expand must never clamp.
            imageCaption.setAttribute('is-expanded', 'false');

            if (!hasHeading) {
              truncatedCaption = handleCaptionTruncation(
                fullCaption,
                maxLength,
              );

              // The collapsed preview is plain text, since a string slice cannot
              // preserve markup. Keep the original nodes so expanding puts the
              // editor's links back instead of more plain text.
              fullCaptionNodes = [...captionContent.childNodes];
              captionContent.textContent = `${truncatedCaption}...`;
            }

            // toggleCaption: set default attributes
            toggleCaption.setAttribute('aria-expanded', 'false');
            toggleCaption.setAttribute('aria-label', 'expand');
            toggleCaption.style.setProperty('display', 'inline');

            collapsibleCaptions.push(imageCaption);

            // Toggle the full caption when the "circle plus" toggle is clicked
            if (!body.hasAttribute('gallery-has-click-event')) {
              toggleCaption.addEventListener('click', function _(e) {
                e.preventDefault();
                const isCurrentlyExpanded =
                  imageCaption.getAttribute('is-expanded') === 'true';

                if (!isCurrentlyExpanded) {
                  toggleCaption.setAttribute('aria-expanded', 'true');
                  toggleCaption.setAttribute('aria-label', 'collapse');
                  if (!hasHeading) {
                    captionContent.replaceChildren(...fullCaptionNodes);
                  }
                  imageCaption.setAttribute('is-expanded', 'true');
                  imageCaption.style.setProperty(
                    '--modal-content-item-height',
                    `${imageCaption.scrollHeight}px`,
                  );
                } else {
                  toggleCaption.setAttribute('aria-expanded', 'false');
                  toggleCaption.setAttribute('aria-label', 'expand');
                  if (!hasHeading) {
                    captionContent.textContent = `${truncatedCaption}...`;
                  }
                  imageCaption.setAttribute('is-expanded', 'false');
                  imageCaption.style.setProperty(
                    '--modal-content-item-height',
                    `${imageCaption.offsetHeight}px`,
                  );
                }
              });
            }
          }
        }
      });

      /**
       * handlePagerClick
       * @description Supports pager navigation.
       */
      const handlePagerClick = (index) => {
        showSelectedItem(index);
      };

      /**
       * handleItemClick
       * @description Active modal on item click.
       */
      const handleItemClick = (item) => {
        const index = Number(
          item
            .closest('[data-media-grid-item]')
            .getAttribute('data-media-grid-item'),
        );
        toggleModalState('inactive');
        showSelectedItem(index);
      };

      /**
       * closeModal
       * @description Close the active modal.
       */
      const closeModal = () => {
        toggleModalState('active');
      };

      /**
       * navigateNext
       * @description Navigate to the next item;
       */
      const navigateNext = () => {
        if (activeIndex === itemCount) {
          showSelectedItem(1);
        } else {
          showSelectedItem(activeIndex + 1);
        }
      };

      /**
       * navigatePrevious
       * @description Navigate to the next item;
       */
      const navigatePrevious = () => {
        if (activeIndex === 1) {
          showSelectedItem(itemCount);
        } else {
          showSelectedItem(activeIndex - 1);
        }
      };

      /**
       * handleSwipe
       * @description Support swiping modal items.
       */
      const handleSwipe = () => {
        // If swipe left, navigate to the next item.
        if (swipeEndX < swipeStartX) {
          navigateNext();
          // If swipe right, navigate to the previous item.
        } else if (swipeEndX > swipeStartX) {
          navigatePrevious();
        }
      };

      // Capture the touch start position for the handleSwipe function.
      modal.addEventListener('touchstart', (e) => {
        swipeStartX = e.changedTouches[0].screenX;
      });

      // Capture the touch end position for the handleSwipe function.
      modal.addEventListener('touchend', (e) => {
        swipeEndX = e.changedTouches[0].screenX;
        handleSwipe();
      });

      // Click and drag (with a mouse) support.
      modalMedia.forEach((media) => {
        const Media = media;

        // Capture the mousedown position for the handleSwipe function.
        media.addEventListener('mousedown', (e) => {
          swipeStartX = e.clientX;
        });

        // Capture the mouseup position for the handleSwipe function.
        media.addEventListener('mouseup', (e) => {
          swipeEndX = e.clientX;
          handleSwipe();
        });

        // Disable browser default behaviors that apply to dragging images.
        Media.ondragstart = () => {
          return false;
        };
      });

      // Show modal when an item's image is clicked.
      items.forEach((item) => {
        item.addEventListener('click', () => {
          handleItemClick(item);
        });
      });

      // Show modal when an item's maximize icon is clicked.
      maximizeIcons.forEach((icon) => {
        icon.addEventListener('click', () => {
          handleItemClick(icon);
        });
      });

      // Navigate to selected pager item.
      pagerItems.forEach((pagerItem, index) => {
        pagerItem.addEventListener('click', () => {
          handlePagerClick(index + 1);
        });
      });

      // Handle modal control clicks.
      controls.forEach((control) => {
        control.addEventListener('click', () => {
          switch (true) {
            // Close modal when the "close" button is clicked.
            case /--close/.test(control.className):
              closeModal();
              break;
            // Navigate to the previous item.
            case /--previous/.test(control.className):
              navigatePrevious();
              break;
            // Navigate to the next item.
            case /--next/.test(control.className):
              navigateNext();
              break;
            default:
              break;
          }
        });
      });

      // Close modal when the "backdrop" is clicked.
      grid.addEventListener('click', (e) => {
        const classesToCheck = [
          'media-grid-modal__inner',
          'media-grid-modal__item',
        ];

        if (
          classesToCheck.some((className) =>
            e.target.classList.contains(className),
          )
        ) {
          closeModal();
        }
      });

      /**
       * expandCaption
       * @description Expands a truncated caption, if it has a toggle.
       * @param {Element} caption the modal caption to expand.
       */
      const expandCaption = (caption) => {
        const toggle = caption.querySelector(
          '.media-grid-modal__toggle-caption',
        );

        // Only a caption long enough to have been truncated has a working
        // toggle; a short one is already showing in full. Clicking it reuses
        // the existing handler rather than duplicating its height bookkeeping.
        if (toggle && toggle.getAttribute('aria-expanded') === 'false') {
          toggle.click();
        }
      };

      /**
       * openItemFromHash
       * @description Opens the gallery item a URL fragment points at.
       *
       * Each caption heading carries a stable id derived from its paragraph,
       * so a link can name one item - notably a Beacon citation pointing at
       * the caption an answer came from. The caption sits behind both the
       * modal and a collapse toggle, so landing the visitor on it takes all
       * three steps a visitor would otherwise take by hand.
       *
       * @param {String} hash the URL fragment, including its leading '#'.
       * @param {Node} scope the DOM the current attach is responsible for.
       */
      const openItemFromHash = (hash, scope) => {
        const id = hash.replace(/^#/, '');

        if (!id) return;

        const target = document.getElementById(id);

        if (!target || !grid.contains(target) || !scope.contains(target)) {
          return;
        }

        const caption = target.closest('.media-grid-modal__content');

        if (!caption) return;

        const index = Number(
          caption.getAttribute('data-media-grid-modal-item'),
        );

        if (!index) return;

        grid.scrollIntoView({
          behavior: window.matchMedia('(prefers-reduced-motion: reduce)')
            .matches
            ? 'auto'
            : 'smooth',
          block: 'start',
        });

        // Same path a click takes, so the dialog gets the same focus trap and
        // the same focus restoration on close.
        if (grid.getAttribute('data-media-grid-modal-state') !== 'active') {
          toggleModalState('inactive');
        }

        showSelectedItem(index);
        expandCaption(caption);

        // Land focus on the heading the fragment names, which carries
        // tabindex="-1" for it. Opening the modal already moves focus inside
        // via trapKeyboard, but a hash arriving while the modal is *already*
        // open only swaps the visible item - which hides whatever was
        // focused and drops focus to the document. Focusing the heading
        // covers both paths and puts the visitor on the cited caption.
        target.focus({ preventScroll: true });
      };

      openItemFromHash(window.location.hash, context);

      // A hash can also arrive after load, from an in-page link or the
      // browser restoring one.
      //
      // One page-level listener that looks up the owning grid, rather than
      // one listener per grid: a per-grid listener on window outlives the
      // grid, so an AJAX re-render would leave it holding this whole closure
      // - grid, modal, items, captions - alive for the life of the page,
      // once per grid replaced. Publishing the opener on the element instead
      // means the only reference to it is the element itself, which is
      // collectable once detached.
      const gridElement = grid;

      gridElement.ysOpenFromHash = openItemFromHash;

      const root = document.documentElement;

      if (!root.hasAttribute('data-media-grid-hash-bound')) {
        root.setAttribute('data-media-grid-hash-bound', 'true');
        window.addEventListener('hashchange', () => {
          const { hash } = window.location;
          const target = document.getElementById(hash.replace(/^#/, ''));
          const owner =
            target &&
            target.closest(
              '.media-grid[data-media-grid-variation="interactive"]',
            );

          if (owner && owner.ysOpenFromHash) {
            owner.ysOpenFromHash(hash, document);
          }
        });
      }

      // Handle key presses.
      grid.addEventListener(
        'keydown',
        (e) => {
          if (e.defaultPrevented) {
            return;
          }

          switch (e.key) {
            case 'Esc':
            case 'Escape':
              // Close modal on escape key press.
              closeModal();
              break;
            case 'Left':
            case 'ArrowLeft':
              // Navigate to the previous item.
              navigatePrevious();
              break;
            case 'Right':
            case 'ArrowRight':
              // Navigate to the next item.
              navigateNext();
              break;
            default:
              return;
          }

          e.preventDefault();
        },
        true,
      );
    });
  },
};
